// ---- lib/config.js ----
/**
 * כל הפרמטרים התפעוליים במקום אחד. שינוי כאן משנה גם את ה-workflows של n8n
 * (הם נבנים מהקוד הזה דרך scripts/build-n8n.mjs).
 */

const CONFIG = {
  /** אזור זמן לתצוגה ולחישוב תזכורות. */
  timezone: 'Asia/Jerusalem',

  /** קידומת מדינה יחידה שאליה מנרמלים כל טלפון. */
  countryCode: '972',

  /** כמה שעות אחרי יצירת הליד נבדק המעקב הראשון. */
  followupHours: 24,

  /** מספר תזכורות אוטומטיות מקסימלי לפני סגירת הליד. */
  maxFollowupAttempts: 2,

  /** כמה שעות לפני התור נשלחת תזכורת ללקוח. */
  appointmentReminderHours: 24,

  /** מתחת לסף הזה סיווג ה-AI נחשב לא בטוח והליד עובר לאדם. */
  minClassificationConfidence: 0.7,

  /** אורך מינימלי של הודעה שנחשבת פנייה אמיתית. */
  minMessageLength: 2,

  /** ערוצים שבהם טלפון הוא שדה חובה (באינסטגרם הוא לא מגיע ב-webhook). */
  phoneRequiredChannels: ['whatsapp', 'form'],

  /** ערוצים נתמכים. */
  channels: ['whatsapp', 'instagram', 'form'],

  /** תוויות הערוצים בגיליון. */
  channelLabels: {
    whatsapp: 'וואטסאפ',
    instagram: 'אינסטגרם',
    form: 'טופס',
  },

  /** דפוסי ספאם — פנייה שתואמת אותם מתויגת "לא רלוונטי" ללא מענה אוטומטי. */
  spamPatterns: [
    /\b(?:bitcoin|crypto|forex|casino|viagra|seo services|backlinks)\b/i,
    /https?:\/\/(?:bit\.ly|tinyurl\.com|t\.me)\//i,
    /הלוואה מיידית|הימורים|הגדלת תנועה לאתר/,
  ],
};

const ESCALATION_REASON = {
  MEDICAL: 'medical',
  COMPLAINT: 'complaint',
  PRICE_NEGOTIATION: 'price_negotiation',
  CANCELLATION_REFUND: 'cancellation_refund',
  PROBLEMATIC_HISTORY: 'problematic_history',
  LOW_CONFIDENCE: 'low_confidence',
};

/** תיאור קריא לכל סיבת הסלמה — נכנס להערות ולהתראה למזכירה. */
const ESCALATION_REASON_LABEL = {
  [ESCALATION_REASON.MEDICAL]: 'שאלה רפואית',
  [ESCALATION_REASON.COMPLAINT]: 'תלונה או חוסר שביעות רצון',
  [ESCALATION_REASON.PRICE_NEGOTIATION]: 'מחיר/הנחה/משא ומתן',
  [ESCALATION_REASON.CANCELLATION_REFUND]: 'ביטול או החזר',
  [ESCALATION_REASON.PROBLEMATIC_HISTORY]: 'ליד חוזר עם היסטוריה בעייתית',
  [ESCALATION_REASON.LOW_CONFIDENCE]: 'ה-AI לא בטוח בסיווג',
};

// ---- lib/statuses.js ----
/**
 * סטטוסים ומעברים חוקיים בצינור הלידים של הקליניקה.
 * מקור אמת יחיד — גם האוטומציה וגם הגיליון משתמשים במחרוזות האלה בדיוק.
 */

const STATUS = {
  NEW: 'חדש',
  CONTACTED: 'נוצר קשר',
  AWAITING_REPLY: 'ממתין לתשובה',
  BOOKED: 'נקבע תור',
  IRRELEVANT: 'לא רלוונטי',
  HANDED_TO_HUMAN: 'הועבר לאדם',
};

const ALL_STATUSES = Object.values(STATUS);

/** סטטוסים סופיים — אין עליהם מעקב אוטומטי. */
const TERMINAL_STATUSES = [STATUS.BOOKED, STATUS.IRRELEVANT];

/** סטטוסים שבהם המעקב האוטומטי פעיל. */
const FOLLOWUP_STATUSES = [STATUS.CONTACTED, STATUS.AWAITING_REPLY];

const TRANSITIONS = {
  [STATUS.NEW]: [STATUS.CONTACTED, STATUS.IRRELEVANT, STATUS.HANDED_TO_HUMAN],
  [STATUS.CONTACTED]: [STATUS.AWAITING_REPLY, STATUS.BOOKED, STATUS.IRRELEVANT, STATUS.HANDED_TO_HUMAN],
  [STATUS.AWAITING_REPLY]: [STATUS.CONTACTED, STATUS.BOOKED, STATUS.IRRELEVANT, STATUS.HANDED_TO_HUMAN],
  // ליד שנסגר יכול להיפתח מחדש כשמגיעה הודעה חדשה מאותו טלפון
  [STATUS.IRRELEVANT]: [STATUS.CONTACTED, STATUS.HANDED_TO_HUMAN],
  [STATUS.HANDED_TO_HUMAN]: [STATUS.BOOKED, STATUS.IRRELEVANT, STATUS.CONTACTED],
  [STATUS.BOOKED]: [STATUS.HANDED_TO_HUMAN, STATUS.IRRELEVANT],
};

function isValidStatus(status) {
  return ALL_STATUSES.includes(status);
}

function canTransition(from, to) {
  if (from === to) return true;
  return (TRANSITIONS[from] || []).includes(to);
}

function isFollowupStatus(status) {
  return FOLLOWUP_STATUSES.includes(status);
}

// ---- lib/phone.js ----
/**
 * נרמול טלפון למפתח ייחודי אחד (E.164).
 * כל מקור מגיע בפורמט אחר: וואטסאפ שולח "972501234567@c.us",
 * אינסטגרם לא שולח טלפון בכלל, וטופס שולח מה שהמשתמש הקליד.
 */

const IL_MOBILE = /^0(?:5\d|7[2-9])\d{7}$/;
const IL_LANDLINE = /^0[23489]\d{7}$/;

function digitsOnly(value) {
  return String(value).replace(/\D/g, '');
}

/**
 * @param {string|number|null|undefined} raw
 * @returns {{ok: true, e164: string, national: string|null, isIsraeli: boolean, type: 'mobile'|'landline'|'unknown'}
 *          |{ok: false, reason: string}}
 */
function normalizePhone(raw) {
  if (raw === null || raw === undefined) return { ok: false, reason: 'missing' };

  const input = String(raw).trim();
  if (!input) return { ok: false, reason: 'missing' };

  // מזהי וואטסאפ/מטא מגיעים כ-"972501234567@c.us" או "972501234567@s.whatsapp.net"
  const stripped = input.split('@')[0].trim();
  const hadInternationalPrefix = stripped.startsWith('+') || /^00\d/.test(stripped.replace(/[\s-]/g, ''));

  let digits = digitsOnly(stripped);
  if (!digits) return { ok: false, reason: 'no_digits' };

  if (digits.startsWith('00')) digits = digits.slice(2);

  const cc = CONFIG.countryCode;
  let national = null;

  if (digits.startsWith(cc) && digits.length > cc.length) {
    national = '0' + digits.slice(cc.length);
  } else if (digits.startsWith('0')) {
    national = digits;
  } else if (!hadInternationalPrefix && digits.length >= 8 && digits.length <= 9) {
    // מספר ישראלי שנכתב בלי אפס מוביל: "501234567"
    national = '0' + digits;
  }

  if (national && (IL_MOBILE.test(national) || IL_LANDLINE.test(national))) {
    return {
      ok: true,
      e164: `+${cc}${national.slice(1)}`,
      national,
      isIsraeli: true,
      type: IL_MOBILE.test(national) ? 'mobile' : 'landline',
    };
  }

  // מספר ישראלי שלא עומד בתבנית — נפסל, אין טעם לשלוח אליו הודעה
  if (national) return { ok: false, reason: 'invalid_israeli_number' };

  // מספר זר תקין באורכו — נשמר כמו שהוא, מסומן כלא-ישראלי
  if (digits.length >= 8 && digits.length <= 15) {
    return { ok: true, e164: `+${digits}`, national: null, isIsraeli: false, type: 'unknown' };
  }

  return { ok: false, reason: 'invalid_length' };
}

/** נוח לשימוש בביטויי n8n: מחזיר מחרוזת או null. */
function toE164(raw) {
  const result = normalizePhone(raw);
  return result.ok ? result.e164 : null;
}

function isValidPhone(raw) {
  return normalizePhone(raw).ok;
}

/** תצוגה ידידותית למזכירה בהתראות. */
function formatForDisplay(e164) {
  const result = normalizePhone(e164);
  if (!result.ok) return String(e164 ?? '');
  if (!result.national) return result.e164;
  return result.type === 'mobile'
    ? `${result.national.slice(0, 3)}-${result.national.slice(3)}`
    : `${result.national.slice(0, 2)}-${result.national.slice(2)}`;
}

// ---- lib/normalize.js ----
/**
 * שלב 1 בצינור — קליטה.
 * שלושת המקורות מגיעים במבנים שונים לחלוטין; כאן הם הופכים למבנה אחיד אחד
 * שכל שאר השלבים מכירים.
 *
 * @typedef {Object} InboundLead
 * @property {'whatsapp'|'instagram'|'form'} channel
 * @property {string} channelLabel  תווית המקור בגיליון
 * @property {string|null} externalId  מזהה ההודעה במקור — לחסימת כפילויות webhook
 * @property {string} fullName
 * @property {string|null} phone  מנורמל ל-E.164, null אם אין/לא תקין
 * @property {string} phoneRaw
 * @property {string} messageText  תוכן הפנייה המקורי
 * @property {string|null} treatmentHint  טיפול שנבחר מראש (טופס בלבד)
 * @property {string} receivedAt  ISO-8601
 * @property {string|null} senderHandle  מזהה לתשובה בערוץ (IGSID / שם משתמש)
 * @property {{channel: string, address: string|null}} replyTo
 * @property {Object} raw
 */

function iso(value, fallbackNow) {
  const now = fallbackNow ? new Date(fallbackNow) : new Date();
  if (value === null || value === undefined || value === '') return now.toISOString();
  // חותמות של מטא/טוויליו מגיעות בשניות, לפעמים כמחרוזת
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) {
    const ms = numeric > 1e11 ? numeric : numeric * 1000;
    return new Date(ms).toISOString();
  }
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? now.toISOString() : parsed.toISOString();
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

/** זיהוי המקור לפי מבנה ה-payload, כדי ש-webhook אחד יוכל לשרת את שלושתם. */
function detectSource(payload = {}) {
  if (payload.object === 'whatsapp_business_account') return 'meta_whatsapp';
  if (payload.object === 'instagram' || payload.object === 'page') return 'meta_instagram';
  if (payload.MessageSid || payload.SmsMessageSid) return 'twilio_whatsapp';
  if (payload.source === 'form' || payload.formId || payload.form_id) return 'form';
  if (payload.channel && CONFIG.channels.includes(payload.channel)) return 'generic';
  return 'unknown';
}

function fromMetaWhatsapp(payload, options) {
  const value = payload?.entry?.[0]?.changes?.[0]?.value ?? {};
  const message = value.messages?.[0] ?? {};
  const contact = value.contacts?.[0] ?? {};
  const text =
    message.text?.body ??
    message.button?.text ??
    message.interactive?.list_reply?.title ??
    message.interactive?.button_reply?.title ??
    '';
  return {
    channel: 'whatsapp',
    externalId: message.id ?? null,
    fullName: clean(contact.profile?.name),
    phoneRaw: clean(message.from ?? contact.wa_id),
    messageText: clean(text),
    treatmentHint: null,
    receivedAt: iso(message.timestamp, options.now),
    senderHandle: message.from ?? null,
  };
}

function fromTwilioWhatsapp(payload, options) {
  return {
    channel: 'whatsapp',
    externalId: payload.MessageSid ?? payload.SmsMessageSid ?? null,
    fullName: clean(payload.ProfileName),
    phoneRaw: clean(String(payload.From ?? '').replace(/^whatsapp:/, '')),
    messageText: clean(payload.Body),
    treatmentHint: null,
    receivedAt: iso(payload.Timestamp ?? payload.DateSent, options.now),
    senderHandle: clean(String(payload.From ?? '')) || null,
  };
}

function fromMetaInstagram(payload, options) {
  const entry = payload?.entry?.[0] ?? {};
  const messaging = entry.messaging?.[0];

  if (messaging) {
    // הודעה פרטית (DM)
    return {
      channel: 'instagram',
      externalId: messaging.message?.mid ?? null,
      fullName: clean(messaging.sender?.username),
      phoneRaw: '',
      messageText: clean(messaging.message?.text),
      treatmentHint: null,
      receivedAt: iso(messaging.timestamp ?? entry.time, options.now),
      senderHandle: messaging.sender?.id ?? messaging.sender?.username ?? null,
    };
  }

  // תגובה לפוסט
  const comment = entry.changes?.[0]?.value ?? {};
  return {
    channel: 'instagram',
    externalId: comment.id ?? null,
    fullName: clean(comment.from?.username ?? comment.username),
    phoneRaw: '',
    messageText: clean(comment.text),
    treatmentHint: null,
    receivedAt: iso(comment.timestamp ?? entry.time, options.now),
    senderHandle: comment.from?.id ?? comment.from?.username ?? comment.username ?? null,
  };
}

function fromForm(payload, options) {
  return {
    channel: 'form',
    externalId: clean(payload.submissionId ?? payload.submission_id ?? payload.id) || null,
    fullName: clean(payload.name ?? payload.fullName ?? payload.full_name),
    phoneRaw: clean(payload.phone ?? payload.tel ?? payload.mobile),
    messageText: clean(payload.message ?? payload.notes ?? payload.text),
    treatmentHint: clean(payload.treatment ?? payload.interest ?? payload.service) || null,
    receivedAt: iso(payload.submittedAt ?? payload.submitted_at ?? payload.createdAt, options.now),
    senderHandle: clean(payload.email) || null,
  };
}

function fromGeneric(payload, options) {
  return {
    channel: payload.channel,
    externalId: clean(payload.externalId) || null,
    fullName: clean(payload.fullName ?? payload.name),
    phoneRaw: clean(payload.phone),
    messageText: clean(payload.messageText ?? payload.message),
    treatmentHint: clean(payload.treatment) || null,
    receivedAt: iso(payload.receivedAt, options.now),
    senderHandle: clean(payload.senderHandle) || null,
  };
}

const PARSERS = {
  meta_whatsapp: fromMetaWhatsapp,
  twilio_whatsapp: fromTwilioWhatsapp,
  meta_instagram: fromMetaInstagram,
  form: fromForm,
  generic: fromGeneric,
};

/**
 * לאן נשלחת התשובה.
 * באינסטגרם אין טלפון — עונים דרך מזהה השולח. בטופס אין ערוץ לענות בו,
 * ולכן התשובה יוצאת בוואטסאפ לטלפון שנמסר, ובאימייל אם אין טלפון.
 */
function replyRoute(parsed, phoneResult) {
  const phone = phoneResult.ok ? phoneResult.e164 : null;
  if (parsed.channel === 'instagram') return { channel: 'instagram', address: parsed.senderHandle ?? null };
  if (parsed.channel === 'form') {
    return phone
      ? { channel: 'whatsapp', address: phone }
      : { channel: 'email', address: parsed.senderHandle ?? null };
  }
  return { channel: parsed.channel, address: phone };
}

/**
 * @param {Object} payload  גוף ה-webhook הגולמי
 * @param {{source?: string, now?: string}} [options]
 * @returns {InboundLead}
 */
function normalizeInbound(payload = {}, options = {}) {
  const source = options.source ?? detectSource(payload);
  const parse = PARSERS[source];

  if (!parse) {
    return {
      channel: 'unknown',
      channelLabel: 'לא ידוע',
      externalId: null,
      fullName: '',
      phone: null,
      phoneRaw: '',
      messageText: '',
      treatmentHint: null,
      receivedAt: iso(null, options.now),
      senderHandle: null,
      replyTo: { channel: 'unknown', address: null },
      source,
      raw: payload,
    };
  }

  const parsed = parse(payload, options);
  const phoneResult = normalizePhone(parsed.phoneRaw);

  return {
    ...parsed,
    fullName: parsed.fullName || 'ללא שם',
    phone: phoneResult.ok ? phoneResult.e164 : null,
    channelLabel: CONFIG.channelLabels[parsed.channel] ?? parsed.channel,
    replyTo: replyRoute(parsed, phoneResult),
    source,
    raw: payload,
  };
}

// ---- lib/validate.js ----
/**
 * שלב 2 בצינור — בדיקת תקינות.
 * פנייה שלא עוברת את הבדיקה מתויגת "לא רלוונטי" ומקבלת התראה קצרה למזכירה,
 * בלי מענה אוטומטי ללקוח.
 *
 * הערה: באינסטגרם אין טלפון ב-webhook. לכן טלפון נדרש רק בערוצים שבהם הוא
 * אמור להגיע (וואטסאפ/טופס); בליד מאינסטגרם הטלפון נאסף בשיחה הראשונה.
 */

const REJECTION = {
  UNKNOWN_CHANNEL: 'unknown_channel',
  EMPTY_MESSAGE: 'empty_message',
  MISSING_PHONE: 'missing_phone',
  INVALID_PHONE: 'invalid_phone',
  SPAM: 'spam',
};

const REJECTION_LABEL = {
  [REJECTION.UNKNOWN_CHANNEL]: 'מקור פנייה לא מזוהה',
  [REJECTION.EMPTY_MESSAGE]: 'פנייה ריקה',
  [REJECTION.MISSING_PHONE]: 'חסר טלפון',
  [REJECTION.INVALID_PHONE]: 'טלפון לא תקין',
  [REJECTION.SPAM]: 'ספאם',
};

function isSpam(text = '') {
  return CONFIG.spamPatterns.some((pattern) => pattern.test(text));
}

/**
 * @param {import('./normalize.js').InboundLead} lead
 * @returns {{valid: boolean, reasons: string[], labels: string[]}}
 */
function validateInbound(lead) {
  const reasons = [];

  if (!CONFIG.channels.includes(lead?.channel)) {
    reasons.push(REJECTION.UNKNOWN_CHANNEL);
  }

  const text = String(lead?.messageText ?? '').trim();
  if (text.length < CONFIG.minMessageLength && !lead?.treatmentHint) {
    reasons.push(REJECTION.EMPTY_MESSAGE);
  }

  if (isSpam(text)) {
    reasons.push(REJECTION.SPAM);
  }

  const phoneRaw = String(lead?.phoneRaw ?? '').trim();
  if (phoneRaw) {
    if (!normalizePhone(phoneRaw).ok) reasons.push(REJECTION.INVALID_PHONE);
  } else if (CONFIG.phoneRequiredChannels.includes(lead?.channel)) {
    reasons.push(REJECTION.MISSING_PHONE);
  }

  return {
    valid: reasons.length === 0,
    reasons,
    labels: reasons.map((reason) => REJECTION_LABEL[reason] ?? reason),
  };
}

// ---- lib/classify.js ----
/**
 * שלב 4 בצינור — סיווג.
 *
 * עיקרון: ה-AI ממיין, מסכם ומנסח — לא מייעץ.
 * לכן ההסלמה לא נשענת רק על שיקול דעת של המודל: יש כאן שכבת כללים
 * דטרמיניסטית שרצה לפני ואחרי ה-AI. גם אם המודל יחליט שהכול תקין,
 * מילה כמו "בהריון" או "החזר כספי" מעבירה את הליד לאדם.
 */

/** רשימת הטיפולים שהקליניקה מציעה — לעריכה לפי הקליניקה בפועל. */
const TREATMENTS = [
  'בוטוקס',
  'חומצה היאלורונית',
  'מילוי שפתיים',
  'לייזר להסרת שיער',
  'טיפולי פנים',
  'פילינג',
  'מזותרפיה',
  'הסרת קעקועים',
  'טיפול אקנה',
  'אחר',
];

const URGENCY = ['נמוכה', 'בינונית', 'גבוהה'];

/** דפוסים שמחייבים העברה לאדם, ללא קשר לדעת המודל. */
const ESCALATION_PATTERNS = [
  {
    reason: ESCALATION_REASON.MEDICAL,
    pattern:
      /בהריון|הריון|מניקה|הנקה|תרופ|אנטיביוטי|רואקוטן|איזוטרטינואין|מדלל(?:י)? דם|תופעות לוואי|אלרגי|סוכרת|יתר לחץ דם|אוטואימונ|מחלת עור|זיהום|כוויה|קוצב לב|ניתוח|מתאים לי|האם מותר|בטוח לי|סיכון|לאחר לידה|מחלה/,
  },
  {
    reason: ESCALATION_REASON.COMPLAINT,
    pattern: /תלונה|לא מרוצ|לא הייתי מרוצ|מאוכזב|גרוע|נזק|התוצאה לא|החמיר|טעות שלכם|כאב לי מאז|לא עבד/,
  },
  {
    reason: ESCALATION_REASON.PRICE_NEGOTIATION,
    pattern: /הנחה|יקר מדי|להוזיל|לשלם פחות|משא ומתן|מחיר מיוחד|תשלומים|מבצע מיוחד|הצעה טובה יותר/,
  },
  {
    reason: ESCALATION_REASON.CANCELLATION_REFUND,
    pattern: /לבטל|ביטול|החזר כספי|כסף בחזרה|זיכוי|לדחות את התור/,
  },
];

/** שאלת מחיר "רגילה" — לא מסלימה, אבל ה-AI לא נוקב במחיר והמזכירה מקבלת ציון לכך. */
const PRICE_QUESTION = /כמה עולה|מה המחיר|מחירון|עלות|כמה זה/;

/**
 * כללים שרצים על הטקסט בלבד.
 * @param {string} text
 * @returns {string[]} סיבות הסלמה
 */
function detectEscalationInText(text = '') {
  const value = String(text);
  return ESCALATION_PATTERNS.filter(({ pattern }) => pattern.test(value)).map(({ reason }) => reason);
}

function mentionsPrice(text = '') {
  return PRICE_QUESTION.test(String(text));
}

/** סכמת הפלט של המודל — JSON בלבד, ללא טקסט חופשי. */
const CLASSIFICATION_SCHEMA = {
  type: 'object',
  properties: {
    requestedTreatment: { type: 'string', enum: TREATMENTS, description: 'הטיפול המבוקש' },
    urgency: { type: 'string', enum: URGENCY },
    requiresHuman: { type: 'boolean', description: 'האם נדרש טיפול של אדם' },
    escalationReasons: {
      type: 'array',
      items: { type: 'string', enum: Object.values(ESCALATION_REASON) },
    },
    summary: { type: 'string', description: 'סיכום הפנייה במשפט אחד, ללא פרשנות רפואית' },
    confidence: { type: 'number', description: 'ביטחון בסיווג, 0 עד 1' },
  },
  required: ['requestedTreatment', 'urgency', 'requiresHuman', 'escalationReasons', 'summary', 'confidence'],
};

const CLASSIFIER_SYSTEM_PROMPT = `אתה מסווג פניות עבור קליניקה לרפואה אסתטית.
תפקידך: למיין, לסכם ולחלץ מידע — לא לייעץ ולא לענות ללקוח.

חוקים מוחלטים:
1. אינך נותן מידע רפואי, אינך קובע התאמה לטיפול ואינך מעריך תוצאה צפויה.
2. אינך נוקב במחירים, בהנחות או בתנאי תשלום.
3. בכל אחד מהמקרים הבאים requiresHuman=true והסיבה נרשמת ב-escalationReasons:
   - medical: שאלה רפואית כלשהי — התאמה לטיפול, תופעות לוואי, הריון/הנקה, תרופות, מחלות רקע.
   - complaint: תלונה או חוסר שביעות רצון מטיפול קודם.
   - price_negotiation: בקשת הנחה, משא ומתן או בקשת מחיר חריגה.
   - cancellation_refund: בקשת ביטול או החזר.
   - problematic_history: הפנייה מציינת היסטוריה בעייתית מול הקליניקה.
   - low_confidence: אינך בטוח בסיווג.
4. אם אינך בטוח — confidence נמוך מ-0.7 ו-requiresHuman=true. עדיף להעביר לאדם מאשר לנחש.
5. requestedTreatment חייב להיות אחד מהערכים המותרים; אם לא ברור, בחר "אחר".
6. summary הוא משפט אחד ענייני בעברית, ללא אבחנה ובלי המלצה.

החזר JSON תקין בלבד, ללא טקסט לפניו או אחריו, ללא סימוני קוד.`;

/**
 * בניית ההודעה למודל.
 * @param {import('./normalize.js').InboundLead} lead
 * @param {{isReturning?: boolean, previousNotes?: string}} [context]
 */
function buildClassifierPrompt(lead, context = {}) {
  const lines = [
    `מקור הפנייה: ${lead.channelLabel ?? lead.channel}`,
    `שם: ${lead.fullName || 'לא ידוע'}`,
    lead.treatmentHint ? `טיפול שנבחר בטופס: ${lead.treatmentHint}` : null,
    context.isReturning ? 'זהו ליד קיים שפנה שוב.' : null,
    context.previousNotes ? `הערות קודמות: ${context.previousNotes}` : null,
    '',
    'תוכן הפנייה:',
    `"""${lead.messageText ?? ''}"""`,
    '',
    `ערכים מותרים ל-requestedTreatment: ${TREATMENTS.join(' | ')}`,
    `ערכים מותרים ל-urgency: ${URGENCY.join(' | ')}`,
  ].filter((line) => line !== null);

  return {
    system: CLASSIFIER_SYSTEM_PROMPT,
    user: lines.join('\n'),
    schema: CLASSIFICATION_SCHEMA,
  };
}

/** המודל עלול להחזיר ```json ...``` למרות ההוראה — כאן מנקים ומפענחים. */
function parseClassifierOutput(raw) {
  if (raw && typeof raw === 'object') return raw;
  const text = String(raw ?? '').trim();
  if (!text) return null;
  const withoutFence = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const start = withoutFence.indexOf('{');
  const end = withoutFence.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return null;
  try {
    return JSON.parse(withoutFence.slice(start, end + 1));
  } catch {
    return null;
  }
}

function sanitizeTreatment(value, hint) {
  if (TREATMENTS.includes(value)) return value;
  if (hint && TREATMENTS.includes(hint)) return hint;
  return 'אחר';
}

/**
 * מיזוג פלט ה-AI עם הכללים הדטרמיניסטיים. זו הפונקציה שמכריעה.
 *
 * @param {Object|string|null} aiOutput  פלט גולמי מהמודל (או null אם הקריאה נכשלה)
 * @param {import('./normalize.js').InboundLead} lead
 * @param {{problematicHistory?: boolean}} [context]
 * @returns {{requestedTreatment: string, urgency: string, requiresHuman: boolean,
 *            escalationReasons: string[], confidence: number, summary: string,
 *            mentionsPrice: boolean, aiFailed: boolean}}
 */
function resolveClassification(aiOutput, lead, context = {}) {
  const parsed = parseClassifierOutput(aiOutput);
  const aiFailed = parsed === null;

  const text = `${lead?.messageText ?? ''} ${lead?.treatmentHint ?? ''}`;
  const reasons = new Set(detectEscalationInText(text));

  for (const reason of parsed?.escalationReasons ?? []) {
    if (Object.values(ESCALATION_REASON).includes(reason)) reasons.add(reason);
  }

  if (context.problematicHistory) reasons.add(ESCALATION_REASON.PROBLEMATIC_HISTORY);

  const rawConfidence = Number(parsed?.confidence);
  const confidence = aiFailed || !Number.isFinite(rawConfidence)
    ? 0
    : Math.min(Math.max(rawConfidence, 0), 1);

  if (aiFailed || confidence < CONFIG.minClassificationConfidence) {
    reasons.add(ESCALATION_REASON.LOW_CONFIDENCE);
  }

  const escalationReasons = [...reasons];

  return {
    requestedTreatment: sanitizeTreatment(parsed?.requestedTreatment, lead?.treatmentHint),
    urgency: URGENCY.includes(parsed?.urgency) ? parsed.urgency : 'בינונית',
    requiresHuman: escalationReasons.length > 0 || parsed?.requiresHuman === true,
    escalationReasons,
    confidence,
    summary: String(parsed?.summary ?? '').trim() || String(lead?.messageText ?? '').slice(0, 140),
    mentionsPrice: mentionsPrice(text),
    aiFailed,
  };
}

// ---- lib/record.js ----
/**
 * מבנה הרשומה בגיליון/CRM ותרגום בין רשומה לשורה.
 * סדר העמודות כאן הוא סדר העמודות בגיליון — אל תשנו אחד בלי השני.
 */

const COLUMNS = [
  { key: 'leadKey', header: 'מפתח ליד' },
  { key: 'fullName', header: 'שם מלא' },
  { key: 'phone', header: 'טלפון' },
  { key: 'source', header: 'מקור הפנייה' },
  { key: 'requestedTreatment', header: 'טיפול מבוקש' },
  { key: 'originalMessage', header: 'תוכן הפנייה המקורי' },
  { key: 'receivedAt', header: 'תאריך ושעת פנייה' },
  { key: 'status', header: 'סטטוס' },
  { key: 'nextFollowupAt', header: 'מועד מעקב הבא' },
  { key: 'followupAttempts', header: 'ניסיונות מעקב' },
  { key: 'owner', header: 'מי מטפל' },
  { key: 'appointmentAt', header: 'תאריך תור' },
  { key: 'notes', header: 'הערות' },
  { key: 'updatedAt', header: 'עדכון אחרון' },
  // עמודות תפעוליות שהאוטומציה צריכה ואינן חלק מהמינימום שהוגדר
  { key: 'urgency', header: 'דחיפות' },
  { key: 'escalationReasons', header: 'סיבות הסלמה' },
  { key: 'confidence', header: 'ביטחון סיווג' },
  { key: 'channelHandle', header: 'מזהה בערוץ' },
  { key: 'lastExternalId', header: 'מזהה הודעה אחרונה' },
  { key: 'problematicHistory', header: 'היסטוריה בעייתית' },
  { key: 'appointmentReminderAt', header: 'מועד תזכורת תור' },
  { key: 'appointmentReminderSent', header: 'תזכורת תור נשלחה' },
];

const HEADERS = COLUMNS.map((column) => column.header);

const OWNER = { AI: 'AI', SECRETARY: 'מזכירה' };

/** מפתח ייחודי לליד. טלפון כשיש; באינסטגרם לפני איסוף טלפון — מזהה השולח. */
function leadKey(lead) {
  if (lead?.phone) return lead.phone;
  if (lead?.senderHandle) return `${lead.channel}:${lead.senderHandle}`;
  return null;
}

function addHours(isoString, hours) {
  return new Date(new Date(isoString).getTime() + hours * 3600 * 1000).toISOString();
}

/** הוספת שורה להערות בלי לדרוס את מה שהיה. */
function appendNote(existingNotes, entry, at) {
  const stamp = new Intl.DateTimeFormat('he-IL', {
    timeZone: CONFIG.timezone,
    dateStyle: 'short',
    timeStyle: 'short',
  }).format(new Date(at));
  const line = `[${stamp}] ${entry}`;
  const previous = String(existingNotes ?? '').trim();
  return previous ? `${previous}\n${line}` : line;
}

/**
 * בניית רשומה חדשה מליד מנורמל + סיווג.
 * @returns {Object} רשומה מוכנה לכתיבה לגיליון
 */
function buildLeadRecord(lead, classification, now) {
  const createdAt = now ?? new Date().toISOString();
  const requiresHuman = classification.requiresHuman;

  return {
    leadKey: leadKey(lead),
    fullName: lead.fullName || 'ללא שם',
    phone: lead.phone ?? '',
    source: lead.channelLabel ?? CONFIG.channelLabels[lead.channel] ?? lead.channel,
    requestedTreatment: classification.requestedTreatment,
    originalMessage: lead.messageText ?? '',
    receivedAt: lead.receivedAt ?? createdAt,
    status: STATUS.NEW,
    nextFollowupAt: addHours(createdAt, CONFIG.followupHours),
    followupAttempts: 0,
    owner: requiresHuman ? OWNER.SECRETARY : OWNER.AI,
    appointmentAt: '',
    notes: appendNote('', `נקלט מ${lead.channelLabel ?? lead.channel}: ${classification.summary}`, createdAt),
    updatedAt: createdAt,
    urgency: classification.urgency,
    escalationReasons: (classification.escalationReasons ?? []).join(','),
    confidence: classification.confidence,
    channelHandle: lead.senderHandle ?? '',
    lastExternalId: lead.externalId ?? '',
    problematicHistory: false,
    appointmentReminderAt: '',
    appointmentReminderSent: false,
  };
}

function toSheetRow(record) {
  return COLUMNS.map(({ key }) => {
    const value = record[key];
    if (value === null || value === undefined) return '';
    if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';
    return String(value);
  });
}

function fromSheetRow(row) {
  const record = {};
  COLUMNS.forEach(({ key }, index) => {
    record[key] = row?.[index] ?? '';
  });
  record.followupAttempts = Number(record.followupAttempts) || 0;
  record.confidence = Number(record.confidence) || 0;
  record.problematicHistory = String(record.problematicHistory).toUpperCase() === 'TRUE';
  record.appointmentReminderSent = String(record.appointmentReminderSent).toUpperCase() === 'TRUE';
  return record;
}

/** המרה מאובייקט בשם-עמודה (כפי שנוד Google Sheets ב-n8n מחזיר) לרשומה. */
function fromSheetObject(object = {}) {
  const record = {};
  for (const { key, header } of COLUMNS) {
    record[key] = object[header] ?? object[key] ?? '';
  }
  record.followupAttempts = Number(record.followupAttempts) || 0;
  record.confidence = Number(record.confidence) || 0;
  record.problematicHistory = String(record.problematicHistory).toUpperCase() === 'TRUE';
  record.appointmentReminderSent = String(record.appointmentReminderSent).toUpperCase() === 'TRUE';
  return record;
}

/** המרה חזרה למפתחות בעברית לכתיבה לגיליון. */
function toSheetObject(record) {
  const object = {};
  for (const { key, header } of COLUMNS) {
    if (record[key] === undefined) continue;
    const value = record[key];
    object[header] = typeof value === 'boolean' ? (value ? 'TRUE' : 'FALSE') : value ?? '';
  }
  return object;
}

