  });
}

/** תגובה ראשונית — אישור קבלה + שאלה אחת לתיאום. */
function greeting(lead) {
  const name = firstName(lead.fullName);
  const hello = name ? `היי ${name},` : 'היי,';
  const treatment = lead.requestedTreatment && lead.requestedTreatment !== 'לא ידוע'
