// ---- lib/pipeline.js ----
/**
 * שלבים 1–7 בצינור, כפונקציה טהורה אחת.
 * הפונקציה לא מדברת עם אף שירות — היא מקבלת מצב ומחזירה רשימת פעולות,
 * ו-n8n/Make מבצע אותן. כך אפשר לבדוק את כל ההיגיון בלי webhooks.
 */

const ACTION = {
  CREATE_RECORD: 'create_record',
  UPDATE_RECORD: 'update_record',
  SEND_MESSAGE: 'send_message',
  NOTIFY_STAFF: 'notify_staff',
};

const OUTCOME = {
  INVALID: 'invalid',
  DUPLICATE_WEBHOOK: 'duplicate_webhook',
  EXISTING_UPDATED: 'existing_updated',
  CREATED: 'created',
};

const sendMessage = (lead, text, kind) => ({
  type: ACTION.SEND_MESSAGE,
  kind,
  channel: lead.replyTo?.channel ?? lead.channel,
  to: lead.replyTo?.address ?? lead.phone ?? null,
  text,
});

const notify = (text, severity = 'info') => ({ type: ACTION.NOTIFY_STAFF, severity, text });

/**
 * @param {Object} input
 * @param {Object} input.payload  גוף ה-webhook הגולמי
 * @param {string} [input.source]  דריסת זיהוי המקור
 * @param {Object|null} [input.existingRecord]  הרשומה הקיימת לאותו מפתח, אם נמצאה
 * @param {Object|string|null} [input.aiOutput]  פלט הסיווג של המודל
 * @param {string} [input.now]  ISO — מוזרק בבדיקות
 * @param {string} [input.sheetUrl]  קישור לשורה, נכנס להתראות
 */
function processInbound({ payload, source, existingRecord = null, aiOutput = null, now, sheetUrl } = {}) {
  const at = now ?? new Date().toISOString();
  const lead = normalizeInbound(payload, { source, now: at });
  const validation = validateInbound(lead);
  const key = leadKey(lead);

  // webhook שנשלח פעמיים — אותו מזהה הודעה, לא עושים כלום
  if (lead.externalId && existingRecord && existingRecord.lastExternalId === lead.externalId) {
    return { outcome: OUTCOME.DUPLICATE_WEBHOOK, lead, validation, actions: [] };
  }

  if (!validation.valid) {
    const actions = [];
    const summary = validation.labels.join(', ');

    if (existingRecord) {
      actions.push({
        type: ACTION.UPDATE_RECORD,
        key: existingRecord.leadKey ?? key,
        updates: {
          notes: appendNote(existingRecord.notes, `פנייה שנפסלה (${summary}): ${lead.messageText}`, at),
          lastExternalId: lead.externalId ?? existingRecord.lastExternalId ?? '',
          updatedAt: at,
        },
      });
    } else if (key) {
      const record = buildLeadRecord(lead, {
        requestedTreatment: 'אחר',
        urgency: 'נמוכה',
        escalationReasons: [],
        requiresHuman: false,
        confidence: 0,
        summary: `פנייה שנפסלה: ${summary}`,
      }, at);
      record.status = STATUS.IRRELEVANT;
      record.owner = OWNER.SECRETARY;
      record.nextFollowupAt = '';
      actions.push({ type: ACTION.CREATE_RECORD, record });
    }

    // אין מענה אוטומטי לפנייה שנפסלה — רק התראה קצרה
    actions.push(notify(messages.invalidLeadAlert(lead, validation.labels, sheetUrl), 'warning'));
    return { outcome: OUTCOME.INVALID, lead, validation, actions };
  }

  const classification = resolveClassification(aiOutput, lead, {
    problematicHistory: Boolean(existingRecord?.problematicHistory),
  });

  return existingRecord
    ? updateExisting({ lead, existingRecord, classification, at, sheetUrl, validation })
    : createNew({ lead, classification, at, sheetUrl, validation });
}

function createNew({ lead, classification, at, sheetUrl, validation }) {
  const record = buildLeadRecord(lead, classification, at);
  const actions = [{ type: ACTION.CREATE_RECORD, record }];

  const alertLead = {
    ...record,
    channel: lead.channel,
    sourceLabel: record.source,
    escalationReasons: classification.escalationReasons,
    originalMessage: lead.messageText,
  };

  if (classification.requiresHuman) {
    // ה-AI לא עונה לגופו של עניין — רק מודיע שמישהו יחזור
    actions.push(sendMessage(lead, messages.handoffToHuman(), 'handoff'));
    actions.push({
      type: ACTION.UPDATE_RECORD,
      key: record.leadKey,
      updates: {
        status: STATUS.HANDED_TO_HUMAN,
        owner: OWNER.SECRETARY,
        nextFollowupAt: '',
        updatedAt: at,
      },
    });
    actions.push(notify(messages.handoffAlert(alertLead, sheetUrl), 'critical'));
    return { outcome: OUTCOME.CREATED, lead, classification, validation, record, actions };
  }

  actions.push(sendMessage(lead, messages.greeting({ ...lead, requestedTreatment: classification.requestedTreatment }), 'greeting'));
  actions.push({
    type: ACTION.UPDATE_RECORD,
    key: record.leadKey,
    updates: { status: STATUS.CONTACTED, updatedAt: at },
  });

  const priceNote = classification.mentionsPrice ? '\n(הלקוח שאל על מחיר — ה-AI לא נוקב במחירים)' : '';
  actions.push(notify(messages.newLeadAlert(alertLead, sheetUrl) + priceNote, 'info'));

  return { outcome: OUTCOME.CREATED, lead, classification, validation, record, actions };
}

function updateExisting({ lead, existingRecord, classification, at, sheetUrl, validation }) {
  const updates = {
    notes: appendNote(existingRecord.notes, `פנייה חוזרת מ${lead.channelLabel}: ${lead.messageText}`, at),
    lastExternalId: lead.externalId ?? existingRecord.lastExternalId ?? '',
    updatedAt: at,
  };

  // טלפון שהגיע רק עכשיו (למשל ליד מאינסטגרם שהשאיר מספר) משלים את הרשומה
  if (!existingRecord.phone && lead.phone) updates.phone = lead.phone;
  if ((!existingRecord.fullName || existingRecord.fullName === 'ללא שם') && lead.fullName !== 'ללא שם') {
    updates.fullName = lead.fullName;
  }

  const actions = [];
  const alertLead = {
    ...existingRecord,
    ...updates,
    channel: lead.channel,
    sourceLabel: existingRecord.source,
    requestedTreatment: existingRecord.requestedTreatment || classification.requestedTreatment,
    escalationReasons: classification.escalationReasons,
    originalMessage: lead.messageText,
  };

  if (classification.requiresHuman && existingRecord.status !== STATUS.HANDED_TO_HUMAN) {
    if (canTransition(existingRecord.status, STATUS.HANDED_TO_HUMAN)) {
      updates.status = STATUS.HANDED_TO_HUMAN;
      updates.owner = OWNER.SECRETARY;
      updates.nextFollowupAt = '';
      updates.escalationReasons = classification.escalationReasons.join(',');
    }
    actions.push({ type: ACTION.UPDATE_RECORD, key: existingRecord.leadKey, updates });
    actions.push(sendMessage(lead, messages.handoffToHuman(), 'handoff'));
    actions.push(notify(messages.handoffAlert(alertLead, sheetUrl), 'critical'));
    return { outcome: OUTCOME.EXISTING_UPDATED, lead, classification, validation, updates, actions };
  }

  // הלקוח הגיב — המעקב מתאפס, אבל לא נשלחת שוב הודעת פתיחה
  const reopenable = [STATUS.AWAITING_REPLY, STATUS.IRRELEVANT];
  if (reopenable.includes(existingRecord.status) && canTransition(existingRecord.status, STATUS.CONTACTED)) {
    updates.status = STATUS.CONTACTED;
    updates.followupAttempts = 0;
    updates.nextFollowupAt = addHours(at, CONFIG.followupHours);
  }

  actions.push({ type: ACTION.UPDATE_RECORD, key: existingRecord.leadKey, updates });
  actions.push(notify(messages.returningLeadAlert(alertLead, sheetUrl), 'info'));

  return { outcome: OUTCOME.EXISTING_UPDATED, lead, classification, validation, updates, actions };
}

// ---- lib/followup.js ----
/**
 * שלבים 8–9 בצינור: המעקב השעתי וקביעת התור.
 * גם כאן — פונקציות טהורות שמחזירות פעולות, בלי קריאות רשת.
 */

const isDue = (isoString, now) => {
  if (!isoString) return false;
  const due = new Date(isoString).getTime();
  return Number.isFinite(due) && due <= new Date(now).getTime();
};

/** לאן שולחים הודעה ללקוח קיים, לפי מה ששמור ברשומה. */
function replyTargetForRecord(record) {
  if (record.phone) return { channel: 'whatsapp', address: record.phone };
  if (record.source === CONFIG.channelLabels.instagram && record.channelHandle) {
    return { channel: 'instagram', address: record.channelHandle };
  }
  return { channel: 'unknown', address: null };
}

function messageAction(record, text, kind) {
  const target = replyTargetForRecord(record);
  return { type: ACTION.SEND_MESSAGE, kind, channel: target.channel, to: target.address, text };
}

/**
 * מה לעשות עם ליד אחד בסריקה השעתית.
 * @param {Object} record  רשומה מהגיליון
 * @param {string} now  ISO
 * @param {string} [sheetUrl]
 * @returns {{due: boolean, reason: string, actions: Array}}
 */
function planFollowup(record, now, sheetUrl) {
  if (!isFollowupStatus(record.status)) {
    return { due: false, reason: 'status_not_eligible', actions: [] };
  }
  if (!isDue(record.nextFollowupAt, now)) {
    return { due: false, reason: 'not_due', actions: [] };
  }

  const attempts = Number(record.followupAttempts) || 0;

  // מיצינו את הניסיונות — סוגרים ומודיעים למזכירה, בלי עוד הודעות ללקוח
  if (attempts >= CONFIG.maxFollowupAttempts) {
    return {
      due: true,
      reason: 'closed_no_answer',
      actions: [
        {
          type: ACTION.UPDATE_RECORD,
          key: record.leadKey,
          updates: {
            status: STATUS.IRRELEVANT,
            owner: OWNER.SECRETARY,
            nextFollowupAt: '',
            notes: appendNote(record.notes, `נסגר אוטומטית אחרי ${attempts} ניסיונות מעקב ללא מענה`, now),
            updatedAt: now,
          },
        },
        { type: ACTION.NOTIFY_STAFF, severity: 'warning', text: messages.noAnswerAlert(record, sheetUrl) },
      ],
    };
  }

  const attempt = attempts + 1;
  return {
    due: true,
    reason: 'reminder_sent',
    actions: [
      messageAction(record, messages.followupReminder(record, attempt), 'followup'),
      {
        type: ACTION.UPDATE_RECORD,
        key: record.leadKey,
        updates: {
          status: STATUS.AWAITING_REPLY,
          followupAttempts: attempt,
          nextFollowupAt: addHours(now, CONFIG.followupHours),
          notes: appendNote(record.notes, `נשלחה תזכורת מעקב (${attempt}/${CONFIG.maxFollowupAttempts})`, now),
          updatedAt: now,
        },
      },
    ],
  };
}

/**
 * הופעל כשהמזכירה (או אינטגרציה ליומן) סימנה "נקבע תור".
 * מבטל מעקבים, שולח אישור, ומתזמן תזכורת יום לפני.
 */
function planAppointmentBooked(record, now, sheetUrl) {
  if (record.status !== STATUS.BOOKED) {
    return { ok: false, reason: 'status_not_booked', actions: [] };
  }
  const appointmentAt = record.appointmentAt ? new Date(record.appointmentAt) : null;
  if (!appointmentAt || Number.isNaN(appointmentAt.getTime())) {
    return {
      ok: false,
      reason: 'missing_appointment_date',
      actions: [{
        type: ACTION.NOTIFY_STAFF,
        severity: 'warning',
        text: `⚠️ הליד סומן "נקבע תור" בלי תאריך תור — ${record.fullName} (${record.phone || 'אין טלפון'})`,
      }],
    };
  }

  const reminderAt = addHours(appointmentAt.toISOString(), -CONFIG.appointmentReminderHours);
  const alreadyPast = new Date(reminderAt).getTime() <= new Date(now).getTime();

  return {
    ok: true,
    reason: 'confirmation_sent',
    actions: [
      messageAction(record, messages.appointmentConfirmation(record), 'appointment_confirmation'),
      {
        type: ACTION.UPDATE_RECORD,
        key: record.leadKey,
        updates: {
          owner: OWNER.SECRETARY,
          nextFollowupAt: '', // ביטול כל מעקב תלוי
          followupAttempts: 0,
          // תור שנקבע לפחות מ-24 שעות מראש לא מקבל תזכורת נפרדת
          appointmentReminderAt: alreadyPast ? '' : reminderAt,
          appointmentReminderSent: alreadyPast,
          notes: appendNote(record.notes, `נקבע תור ל-${messages.formatAppointment(record.appointmentAt)}, נשלח אישור`, now),
          updatedAt: now,
        },
      },
    ],
  };
}

/** תזכורת יום לפני התור — נבדקת באותה סריקה שעתית. */
function planAppointmentReminder(record, now) {
  if (record.status !== STATUS.BOOKED) return { due: false, reason: 'status_not_booked', actions: [] };
  if (record.appointmentReminderSent === true) return { due: false, reason: 'already_sent', actions: [] };
  if (!isDue(record.appointmentReminderAt, now)) return { due: false, reason: 'not_due', actions: [] };
  if (new Date(record.appointmentAt).getTime() <= new Date(now).getTime()) {
    return { due: false, reason: 'appointment_passed', actions: [] };
  }

  return {
    due: true,
    reason: 'reminder_sent',
    actions: [
      messageAction(record, messages.appointmentReminder(record), 'appointment_reminder'),
      {
        type: ACTION.UPDATE_RECORD,
        key: record.leadKey,
        updates: {
          appointmentReminderSent: true,
          appointmentReminderAt: '',
          notes: appendNote(record.notes, 'נשלחה תזכורת יום לפני התור', now),
          updatedAt: now,
        },
      },
    ],
  };
}

/**
 * הסריקה השעתית על כל הגיליון.
 * @param {Object[]} records
 * @param {string} now
 * @returns {{actions: Array, summary: Object}}
 */
function planHourlyScan(records = [], now, sheetUrl) {
  const actions = [];
  const summary = { scanned: records.length, reminders: 0, closed: 0, appointmentReminders: 0 };

  for (const record of records) {
    const followup = planFollowup(record, now, sheetUrl);
    if (followup.due) {
      actions.push(...followup.actions);
      if (followup.reason === 'reminder_sent') summary.reminders += 1;
      if (followup.reason === 'closed_no_answer') summary.closed += 1;
      continue;
    }

    const reminder = planAppointmentReminder(record, now);
    if (reminder.due) {
      actions.push(...reminder.actions);
      summary.appointmentReminders += 1;
    }
  }

  return { actions, summary };
}

// ---- מרחב השמות messages ----
const messages = { formatAppointment, greeting, handoffToHuman, followupReminder, appointmentConfirmation, appointmentReminder, newLeadAlert, handoffAlert, invalidLeadAlert, noAnswerAlert, returningLeadAlert };

// ---- תכנון הסריקה השעתית ----
const records = $input.all().map((item) => fromSheetObject(item.json));
const { actions, summary } = planHourlyScan(records, new Date().toISOString(), $env.CLINIC_LEADS_SHEET_URL);
console.log('סריקת מעקב:', JSON.stringify(summary));
const items = [];
for (const action of actions) {
  if (action.type === ACTION.CREATE_RECORD) {
    items.push({ json: { ...action, row: toSheetObject(action.record) } });
  } else if (action.type === ACTION.UPDATE_RECORD) {
    items.push({ json: { ...action, row: { ...toSheetObject(action.updates), 'מפתח ליד': action.key } } });
  } else {
    items.push({ json: action });
  }
}
return items;
